import os
import sys
import tempfile
from flask import Flask, request, render_template_string, send_file

sys.path.insert(0, os.path.dirname(__file__))
from engine import load_and_compute, generate_html

app = Flask(__name__)
UPLOAD_DIR = os.path.join(os.path.dirname(__file__), "output")
os.makedirs(UPLOAD_DIR, exist_ok=True)

# Real Wisdom logo, embedded so the UI is self-contained.
LOGO_WHITE = "data:image/png;base64,"   # white wordmark for the teal header
LOGO_COLOR = "data:image/png;base64,"   # full-color wordmark (unused in UI, kept for reference)

FORM_HTML = r"""
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Wisdom Statement Generator</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Inter:wght@400;500;600&display=swap" rel="stylesheet">
  <style>
    :root {
      --teal-900:#143b46; --teal-700:#1f5d6e; --teal-600:#2a6b7c;
      --teal-400:#4bacc6; --teal-50:#f0f9fc; --teal-100:#d9f0f7;
      --ink:#1c2529; --muted:#5b6b72; --hair:#e3e9ec; --bg:#eef2f4;
      --pos:#1f5d6e; --neg:#b4453b; --surface:#ffffff;
    }
    * { box-sizing: border-box; }
    html, body { margin: 0; padding: 0; }
    body {
      font-family: 'Inter', -apple-system, sans-serif;
      background: var(--bg); color: var(--ink);
      min-height: 100vh;
      background-image: radial-gradient(1200px 500px at 50% -10%, rgba(75,172,198,.16), transparent 60%);
    }

    /* ---- Branded header ---- */
    .topbar {
      background: linear-gradient(100deg, var(--teal-900), var(--teal-600));
      padding: 18px 28px; display: flex; align-items: center; gap: 14px;
      box-shadow: 0 1px 0 rgba(0,0,0,.08);
    }
    .topbar img { height: 30px; width: auto; display: block; }
    .topbar .divider { width: 1px; height: 26px; background: rgba(255,255,255,.28); }
    .topbar .app-name {
      color: #fff; font-family: 'DM Sans', sans-serif; font-weight: 600;
      font-size: .98rem; letter-spacing: .01em; opacity: .95;
    }

    /* ---- Layout ---- */
    .wrap { max-width: 620px; margin: 44px auto 60px; padding: 0 20px; }
    .card {
      background: var(--surface); border-radius: 16px;
      box-shadow: 0 8px 30px rgba(20,59,70,.10), 0 1px 3px rgba(20,59,70,.06);
      border: 1px solid var(--hair); padding: 40px 44px; overflow: hidden;
    }
    h1 {
      font-family: 'DM Sans', sans-serif; margin: 0 0 6px; font-size: 1.6rem;
      font-weight: 700; color: var(--teal-900); letter-spacing: -.01em;
    }
    p.sub { margin: 0 0 30px; color: var(--muted); font-size: .95rem; line-height: 1.5; }

    label { display: block; font-family:'DM Sans',sans-serif; font-size: .82rem;
            font-weight: 600; color: var(--teal-900); margin: 0 0 7px; }
    .field { margin-bottom: 22px; }
    input[type=text] {
      width: 100%; padding: 11px 14px; border: 1px solid var(--hair);
      border-radius: 9px; font-size: .95rem; font-family: 'Inter', sans-serif;
      color: var(--ink); background: #fff; transition: border-color .15s, box-shadow .15s;
    }
    input[type=text]:focus {
      outline: none; border-color: var(--teal-400);
      box-shadow: 0 0 0 3px rgba(75,172,198,.18);
    }

    /* ---- Dropzone ---- */
    .dropzone {
      position: relative; border: 1.5px dashed var(--teal-400);
      border-radius: 12px; background: var(--teal-50);
      padding: 22px 18px; text-align: center; cursor: pointer;
      transition: background .15s, border-color .15s;
    }
    .dropzone:hover { background: var(--teal-100); }
    .dropzone.dragover { background: var(--teal-100); border-color: var(--teal-600); }
    .dropzone.has-file { border-style: solid; border-color: var(--teal-600); background: #fff; }
    .dropzone input[type=file] {
      position: absolute; inset: 0; opacity: 0; cursor: pointer; width: 100%; height: 100%;
    }
    .dz-icon { color: var(--teal-600); font-size: 1.5rem; line-height: 1; margin-bottom: 6px; }
    .dz-title { font-family:'DM Sans',sans-serif; font-weight: 600; font-size: .9rem; color: var(--teal-900); }
    .dz-hint  { font-size: .8rem; color: var(--muted); margin-top: 3px; }
    .dz-file  { font-size: .85rem; color: var(--teal-700); font-weight: 600; margin-top: 8px; word-break: break-all; display:none; }
    .dropzone.has-file .dz-file { display:block; }
    .dropzone.has-file .dz-hint { display:none; }
    .optional-tag {
      display:inline-block; font-family:'Inter',sans-serif; font-weight:500;
      font-size:.68rem; letter-spacing:.04em; text-transform:uppercase;
      color: var(--muted); background: #eef2f4; border-radius: 20px;
      padding: 2px 9px; margin-left: 8px; vertical-align: middle;
    }
    .field-help { font-size:.8rem; color:var(--muted); margin: 7px 0 0; line-height:1.45; }

    /* ---- Submit + spinner ---- */
    button.submit {
      background: var(--teal-600); color: #fff; border: none; border-radius: 10px;
      padding: 13px 28px; font-size: 1rem; font-family:'DM Sans',sans-serif; font-weight: 600;
      cursor: pointer; width: 100%; margin-top: 6px;
      display: inline-flex; align-items: center; justify-content: center; gap: 10px;
      transition: background .15s;
    }
    button.submit:hover { background: var(--teal-700); }
    button.submit:disabled { opacity: .75; cursor: default; }
    .spinner {
      width: 16px; height: 16px; border: 2px solid rgba(255,255,255,.45);
      border-top-color: #fff; border-radius: 50%; display: none; animation: spin .7s linear infinite;
    }
    button.submit.loading .spinner { display: inline-block; }
    @keyframes spin { to { transform: rotate(360deg); } }

    /* ---- Result panel ---- */
    .result {
      border: 1px solid var(--teal-100); background: var(--teal-50);
      border-radius: 12px; padding: 20px 22px; margin-bottom: 28px;
    }
    .result .rtitle {
      font-family:'DM Sans',sans-serif; font-weight: 700; color: var(--teal-900);
      font-size: 1rem; display: flex; align-items: center; gap: 8px; margin-bottom: 4px;
    }
    .result .check {
      width: 20px; height: 20px; border-radius: 50%; background: var(--pos); color:#fff;
      display: inline-flex; align-items:center; justify-content:center; font-size:.72rem; flex:none;
    }
    .result .rmeta { color: var(--muted); font-size: .85rem; margin: 0 0 16px; }
    .result .rmeta b { color: var(--teal-700); }
    .actions { display: flex; gap: 12px; flex-wrap: wrap; }
    .btn-link {
      flex: 1 1 0; min-width: 150px; text-align: center; padding: 11px 14px;
      border-radius: 9px; text-decoration: none; font-family:'DM Sans',sans-serif;
      font-size: .92rem; font-weight: 600; transition: background .15s, border-color .15s;
    }
    .btn-pdf  { background: var(--teal-600); color: #fff; }
    .btn-pdf:hover { background: var(--teal-700); }
    .btn-html { background: #fff; color: var(--teal-700); border: 1px solid var(--teal-400); }
    .btn-html:hover { background: var(--teal-50); }

    .error {
      background: #fdf1f0; border: 1px solid #f0c3bd; border-radius: 10px;
      color: var(--neg); padding: 13px 16px; margin-bottom: 24px; font-size: .9rem; line-height:1.45;
    }
    .divider-h { border: none; border-top: 1px solid var(--hair); margin: 30px 0 26px; }
    .footnote { text-align:center; color: var(--muted); font-size:.78rem; margin-top: 22px; }
  </style>
</head>
<body>
  <div class="topbar">
    <img src="{{ logo_white }}" alt="Wisdom Group Holdings Limited">
    <div class="divider"></div>
    <div class="app-name">Statement Generator</div>
  </div>

  <div class="wrap">
    <div class="card">
      <h1>Consolidated Statement</h1>
      <p class="sub">Upload a position CSV to generate a client-ready consolidated statement.</p>

      {% if error %}
      <div class="error">{{ error }}</div>
      {% endif %}

      {% if html_name %}
      <div class="result">
        <div class="rtitle"><span class="check">&#10003;</span> Statement generated</div>
        <p class="rmeta">Client <b>{{ client }}</b> &middot; RM <b>{{ rm }}</b>{% if compared %} &middot; <b>period-over-period</b> comparison included{% endif %}</p>
        <div class="actions">
          {% if pdf_name %}<a class="btn-link btn-pdf" href="/download/pdf/{{ pdf_name }}">Download PDF</a>{% endif %}
          <a class="btn-link btn-html" href="/preview/{{ html_name }}" target="_blank">Preview HTML</a>
        </div>
      </div>
      <hr class="divider-h">
      {% endif %}

      <form method="post" enctype="multipart/form-data" id="genform">
        <div class="field">
          <label>Position CSV</label>
          <div class="dropzone" id="dz-current">
            <input type="file" name="csv_file" accept=".csv" required
                   onchange="showFile(this,'dz-current')">
            <div class="dz-icon">&#8682;</div>
            <div class="dz-title">Drop CSV here or click to browse</div>
            <div class="dz-hint">Current position snapshot &middot; .csv</div>
            <div class="dz-file"></div>
          </div>
        </div>

        <div class="field">
          <label>Client name</label>
          <input type="text" name="client" value="{{ client or '' }}" placeholder="e.g. Wisdom Group Holdings" required>
        </div>

        <div class="field">
          <label>Relationship Manager</label>
          <input type="text" name="rm" value="{{ rm or '' }}" placeholder="Type your name here" required>
        </div>

        <button type="submit" class="submit" id="submitbtn">
          <span class="spinner"></span>
          <span class="btn-label">Generate Statement</span>
        </button>
      </form>

      <p class="footnote">Wisdom Group Holdings Limited &middot; Consolidated reporting</p>
    </div>
  </div>

  <script>
    function showFile(input, zoneId) {
      var zone = document.getElementById(zoneId);
      var out  = zone.querySelector('.dz-file');
      if (input.files && input.files.length) {
        out.textContent = '\u{1F4C4}  ' + input.files[0].name;
        zone.classList.add('has-file');
      } else {
        out.textContent = '';
        zone.classList.remove('has-file');
      }
    }
    // Drag-over visual feedback
    document.querySelectorAll('.dropzone').forEach(function(zone){
      ['dragenter','dragover'].forEach(function(ev){
        zone.addEventListener(ev, function(e){ e.preventDefault(); zone.classList.add('dragover'); });
      });
      ['dragleave','drop'].forEach(function(ev){
        zone.addEventListener(ev, function(e){ e.preventDefault(); zone.classList.remove('dragover'); });
      });
    });
    // Loading state on submit
    document.getElementById('genform').addEventListener('submit', function(){
      var btn = document.getElementById('submitbtn');
      btn.classList.add('loading');
      btn.disabled = true;
      btn.querySelector('.btn-label').textContent = 'Generating\u2026';
    });
  </script>
</body>
</html>
"""


@app.route("/", methods=["GET", "POST"])
def index():
    if request.method == "GET":
        return render_template_string(FORM_HTML, logo_white=LOGO_WHITE)

    csv_file   = request.files.get("csv_file")
    prior_file = request.files.get("prior_file")
    client = request.form.get("client", "").strip()
    rm     = request.form.get("rm", "").strip()

    if not csv_file or not csv_file.filename:
        return render_template_string(FORM_HTML, logo_white=LOGO_WHITE,
                                      error="Please select a position CSV file.",
                                      client=client, rm=rm)

    # Save the current CSV (and optional prior CSV) to temp files.
    tmp = tempfile.NamedTemporaryFile(suffix=".csv", delete=False)
    csv_file.save(tmp.name); tmp.close()

    prior_tmp_name = None
    if prior_file and prior_file.filename:
        ptmp = tempfile.NamedTemporaryFile(suffix=".csv", delete=False)
        prior_file.save(ptmp.name); ptmp.close()
        prior_tmp_name = ptmp.name

    try:
        data = load_and_compute(tmp.name)

        # Optional period-over-period comparison.
        prior_data = load_and_compute(prior_tmp_name) if prior_tmp_name else None

        html_str = generate_html(
            data,
            os.path.join(os.path.dirname(__file__), "template.html"),
            client, rm, prior=prior_data,
        )

        base = os.path.splitext(csv_file.filename)[0]
        html_name = base + "_statement.html"
        html_path = os.path.join(UPLOAD_DIR, html_name)

        with open(html_path, "w", encoding="utf-8") as f:
            f.write(html_str)

        pdf_name = None
        try:
            from weasyprint import HTML as WP_HTML
            pdf_name = base + "_statement.pdf"
            pdf_path = os.path.join(UPLOAD_DIR, pdf_name)
            WP_HTML(string=html_str).write_pdf(pdf_path)
        except Exception:
            pass  # WeasyPrint unavailable; HTML-only mode

    except Exception as e:
        return render_template_string(FORM_HTML, logo_white=LOGO_WHITE,
                                      error=str(e), client=client, rm=rm)
    finally:
        os.unlink(tmp.name)
        if prior_tmp_name:
            os.unlink(prior_tmp_name)

    return render_template_string(
        FORM_HTML, logo_white=LOGO_WHITE,
        pdf_name=pdf_name, html_name=html_name,
        client=client, rm=rm, compared=bool(prior_tmp_name),
    )


@app.route("/download/pdf/<path:name>")
def download_pdf(name):
    path = os.path.join(UPLOAD_DIR, os.path.basename(name))
    return send_file(path, as_attachment=True, download_name=name)


@app.route("/preview/<path:name>")
def preview_html(name):
    path = os.path.join(UPLOAD_DIR, os.path.basename(name))
    return send_file(path, mimetype="text/html")


if __name__ == "__main__":
    app.run(debug=True, port=5050)
